<script setup lang="ts">import {ref,computed,onMounted,watch} from 'vue';import {useResearch} from '../stores/research';import {useTask} from '../hooks/useTask';import {usePolling} from '../hooks/usePolling';import {num,pvalue,median} from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import StatusBadge from '../components/common/StatusBadge.vue';import RunSelect from '../components/RunSelect.vue';import GradeDots from '../components/GradeDots.vue';import PairFamilyTable from '../components/PairFamilyTable.vue';const research=useResearch(),{error,perform}=useTask(),tab=ref('omnibus'),gCode=ref(''),page=ref(0);const r=computed(()=>research.current?.status==='completed'?research.current.result:null),group=computed(()=>r.value?.groups.find(g=>g.code===gCode.value));watch(r,value=>{if(!value)return;if(!value.groups.some(g=>g.code===gCode.value))gCode.value=value.groups[0]?.code||'';},{immediate:true});watch(()=>research.selected,()=>{page.value=0});onMounted(()=>perform(research.loadRuns));usePolling(research.loadRuns);</script><template><PageHeading no="04" title="完整检验结果" sub="总体分布证据、全部组对与并列来源，在同一份冻结检验里阅读。"/><RunSelect/><ErrorNotice :error="error"/><div v-if="!research.current" class="empty"><h2>还没有结果折页</h2><p>先冻结完整研究并排队，worker计算后可阅读。</p><RouterLink to="/runs">前往运行 →</RouterLink></div><div v-else-if="!r" class="empty"><StatusBadge :status="research.current.status"/><h2>{{research.current.name}}</h2><p>{{research.current.error||'后台尚未完成，结果会自动刷新。'}}</p><RouterLink to="/data">返回核对来源 →</RouterLink></div><template v-if="r&&research.current"><div class="result-byline"><b>#{{research.current.id}} {{research.current.name}}</b><span>全{{r.k}}组 / N={{r.n}} / α={{r.alpha}}</span></div><div class="result-metrics"><div><small>并列修正 H</small><strong>{{num(r.h,5)}}</strong><span>χ²渐近 / df {{r.df}}</span></div><div><small>总体渐近 p</small><strong>{{pvalue(r.p_asymptotic)}}</strong><span>{{r.omnibus_reject?'在预设α下拒绝总体零假设':'未拒绝，不证明分布相同'}}</span></div><div><small>并列修正 C</small><strong>{{num(r.tie_correction,6)}}</strong><span>全部N共同并列项</span></div><div><small>Dunn完整家族</small><strong>{{r.family_size}}<i>组对</i></strong><span>全部Holm校正 / 未筛选</span></div></div><div class="result-tabs"><button :class="{active:tab==='omnibus'}" @click="tab='omnibus'">总体与等级分布</button><button :class="{active:tab==='pairs'}" @click="tab='pairs'">全部组对 / Holm</button><button :class="{active:tab==='ties'}" @click="tab='ties'">并列与平均秩留档</button></div><div v-if="tab==='omnibus'" class="omnibus-spread"><section><h2 class="ruled-title">独立试样的等级分布</h2><GradeDots :treatments="r.groups" :readings="r.ranked_readings"/><p class="muted">总体检验针对组间分布差异。只有额外的相同形状/位置移动假设下，才可把差异聚焦到位置；形状差异也可能使其拒绝。</p></section><aside v-if="group" class="group-detail"><p class="eyebrow">READ ONE GROUP / 核对一个工艺</p><label>工艺<select aria-label="结果工艺详情" v-model="gCode"><option v-for="g in r.groups" :key="g.id" :value="g.code">{{g.code}} {{g.name}}</option></select></label><h2>{{group.code}} · {{group.name}}</h2><dl><div><dt>独立试样</dt><dd>{{group.n}}</dd></div><div><dt>合并秩和</dt><dd>{{num(group.rank_sum,2)}}</dd></div><div><dt>合并平均秩</dt><dd>{{num(group.mean_rank,4)}}</dd></div><div><dt>下 / 上中位等级</dt><dd>{{median(group.median_lower,group.median_upper)}}</dd></div></dl><p class="muted">偶数样本保留两个中位位置的原等级，不插值成“3.5级”。平均秩是共同排序的位置，不是平均性能。</p><aside class="margin-note">样本独立性来自试样设计，不能从等级值自动验证。本研究不是重复测量/配对检验；同批相关可能影响渐近解释。</aside></aside></div><section v-if="tab==='pairs'"><h2 class="ruled-title">预定义的全部{{r.family_size}}组对 <small>同一合并秩方差，双侧正态渐近p</small></h2><PairFamilyTable :pairs="r.pairs" :alpha="r.alpha"/><div class="method-note"><b>Holm是完整家族的顺序校正</b><p>按原始p升序乘以剩余家族数，并取累积最大值、截至1。无论KW总体是否拒绝，全部组对原样保留；未拒绝不表示等效或相同。</p><p>SE² = {{num(r.dunn_variance,6)}} × (1/nᵢ + 1/nⱼ)。差值是合并秩均值差，不能读成等级单位的效应。</p></div></section><section v-if="tab==='ties'"><h2 class="ruled-title">全部N的并列来源 <small>H原始={{num(r.h_raw,6)}} / C={{num(r.tie_correction,6)}}</small></h2><div class="tie-spread"><div class="table-scroll"><table><thead><tr><th>等级</th><th>全N数量 t</th><th>平均秩</th><th>t³−t</th></tr></thead><tbody><tr v-for="t in r.ties" :key="t.grade"><td class="grade-value">{{t.grade}}</td><td>{{t.count}}</td><td>{{num(t.average_rank,2)}}</td><td>{{t.term}}</td></tr></tbody></table></div><aside class="method-note"><p>Σ(t³−t) = {{r.tie_term}}</p><p>C = 1 − Σ(t³−t)/(N³−N)</p><p>Dunn方差基数 = N(N+1)/12 − Σ(t³−t)/(12(N−1)) = {{num(r.dunn_variance,6)}}</p><p>全部试样只排一次秩；组对不另外重排。</p></aside></div><h2 class="ruled-title archive-title">逐份平均秩留档 <small>{{r.ranked_readings.length}}份 / 每页20份</small></h2><div class="table-scroll"><table><thead><tr><th>独立试样</th><th>工艺</th><th>形成等级</th><th>全N合并平均秩</th></tr></thead><tbody><tr v-for="reading in r.ranked_readings.slice(page*20,(page+1)*20)" :key="reading.id"><td>{{reading.specimen_code}}</td><td>{{r.groups.find(g=>g.id===reading.treatment_id)?.code}}</td><td>{{reading.grade}}</td><td>{{num(reading.pooled_rank,2)}}</td></tr></tbody></table></div><div class="button-row"><button :disabled="page===0" @click="page--">上一页</button><span>{{page+1}} / {{Math.ceil(r.ranked_readings.length/20)}}</span><button :disabled="(page+1)*20>=r.ranked_readings.length" @click="page++">下一页</button></div></section><div class="result-boundary"><b>解释边界</b><p>这里的p是χ²/正态渐近近似，不是exact。等级有序、非等距；分布差异不等于纯中位数差，更不证明工艺原因或性能概率。</p><RouterLink to="/notes">提出独立复检问题 →</RouterLink></div><div class="fingerprint">冻结输入 SHA256 <code>{{r.fingerprint}}</code></div></template></template>